-- Guards against drift between `conf/template.yaml` (what the README, CI, and `docker/generate-config.sh`
-- start from) and the parser in `Zocalo.Common.ConfigReader`.
--
-- `stack test` runs with the package root as the working directory, so the relative path below resolves.

module Zocalo.Common.ConfigTemplateSpec(tests) where

import Data.Yaml(decodeFileEither, ParseException)

import Test.Framework(Test, testGroup)
import Test.Framework.Providers.HUnit(testCase)
import Test.HUnit(assertFailure)

import Zocalo.Common.ConfigReader(AppConfig)


tests :: Test
tests =
  testGroup "conf/template.yaml"
    [ testCase "parses with the application's own config parser" $ do
        result <- decodeFileEither "conf/template.yaml" :: IO (Either ParseException AppConfig)
        case result of
          Left err -> assertFailure $ show err
          Right _  -> return ()
    ]
